import{_ as a,H as s,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"38 | 倒排索引：搜索引擎是如何做全文检索的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"飞花令","slug":"飞花令","link":"#飞花令","children":[]},{"level":2,"title":"倒排索引","slug":"倒排索引","link":"#倒排索引","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}]}],"relativePath":"业务开发算法50讲/38｜倒排索引：搜索引擎是如何做全文检索的？.md","filePath":"业务开发算法50讲/38｜倒排索引：搜索引擎是如何做全文检索的？.md","lastUpdated":1795537005000}'),p={name:"业务开发算法50讲/38｜倒排索引：搜索引擎是如何做全文检索的？.md"};function n(l,e,h,o,r,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_38-倒排索引-搜索引擎是如何做全文检索的" tabindex="-1">38 | 倒排索引：搜索引擎是如何做全文检索的？ <a class="header-anchor" href="#_38-倒排索引-搜索引擎是如何做全文检索的" aria-label="Permalink to &quot;38 | 倒排索引：搜索引擎是如何做全文检索的？&quot;">​</a></h1><p>你好，我是微扰君。今天我们来聊一聊倒排索引算法。</p><p>倒排索引算法，作为一种经典的索引方式，在工业界中应用非常广泛，比如搜索引擎、推荐系统、广告系统等等。在广告系统中，我们需要根据定向信息去广告库中召回合适的广告；在搜索引擎中，需要根据某个关键字返回若干搜索结果，如何做得又快又准，就离不开倒排索引的加持了。</p><p>那倒排索引背后的思想到底是什么呢？就让我们来一探究竟吧。</p><h2 id="飞花令" tabindex="-1">飞花令 <a class="header-anchor" href="#飞花令" aria-label="Permalink to &quot;飞花令&quot;">​</a></h2><p>首先，我们来看一个生活中的例子，理解一下倒排索引的大致作用机制。</p><p>不知道你喜不喜欢电影，因为我和几个朋友都很喜欢看电影，一块出去吃饭的时候，我们就会玩一个电影元素的接龙游戏，规则很简单：给定一个电影元素，然后每人轮流快速说出一个和这个元素相关的电影，谁能战到最后，谁就能免单其他人请客，比如元素是“海盗”，有关的电影就有《加勒比海盗》《菲利普船长》等等。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/38/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/38/1.png" alt=""></a></p><p>别看规则简单，其实这个游戏难度很高。因为，即使你看过很多和这个元素相关的电影，你也很难马上想到这些电影，而在别人真的说出这个你看过的某个电影时，你其实又很容易回想起这个元素和该电影的关联。</p><p>这也是这个游戏的乐趣所在。古人们爱玩的飞花令也正是这样一种本质上是反向信息检索的游戏（关键词是“花”，按“花”字的位置接龙背诗，比如第一个人“花”要在诗第一个字，第二个人“花”在诗句的第二个字）。</p><p>这背后显然和人脑对数据检索的方式有关。我们的大脑存储信息的时候，建立了一种和索引很相似的机制：给定一个电影名，你是很容易马上想起电影内容的，但反过来则困难很多。</p><h2 id="倒排索引" tabindex="-1">倒排索引 <a class="header-anchor" href="#倒排索引" aria-label="Permalink to &quot;倒排索引&quot;">​</a></h2><p>面对这个问题，如果我们能建立一种从电影元素到电影名的索引，这个事情就会简单很多了。而这样的索引，我们在小时候读书的时候其实就遇到过。</p><p>我们的英语课本上，书本最后会有一个单词表，每个单词后面除了释义，还会写出在课本中出现的页码信息，这样我们复习单词的时候，就可以根据这个表快速找到对应的课文，并回忆老师讲解的内容了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/38/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/38/2.png" alt=""></a></p><ul><li>图片来自网络</li></ul><p>事实上，这个表就是一种在全文检索的场景下的倒排索引，它记录了每个单词在哪些文档中出现的信息，可以帮助我们快速信息检索。</p><p>类似地，当我们使用搜索引擎根据某些关键词搜索网页的时候，背后非常关键的一个技术就是倒排索引技术。</p><p>根据关键词搜索时，我们可以把网页的内容看成是全文检索的文档，当用户想要根据某个关键词对文档进行查询匹配的时候，如果没有任何倒排索引，我们所能做的就是在数据库中对每个文档进行全文遍历，查看其中是否出现某个关键词，写成 SQL 语句类似这样：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> content </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pages </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> content </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> \`%keyword%\`</span></span></code></pre></div><p>但是，在互联网海量数据的场景下，这样的查询效率显然是没有办法被接受的。</p><p>解决方式就是用空间换时间，在搜索引擎中引入倒排索引，提前预处理存储的全部数据，整理出每个单词到网页 ID 的映射关系，并记录下来；这样我们就可以得到单词到倒排列表的映射，从而快速查询关键词匹配的网页。有了倒排索引后，我们也很容易对多个关键词做与查询。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/38/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/38/3.png" alt=""></a></p><p>还是来举一个具体的例子帮助你理解这个过程。比如我们现在有这样 4 个文档：</p><ol><li><p>极客时间 App，为用户提供前沿的 IT 技术、产品设计、摄影跑步等知识服务。</p></li><li><p>微扰理论是极客时间上喜爱算法、喜爱学习的一个用户。</p></li><li><p>微扰理论是从相关问题的确切解中找出问题的近似解的数学方法。</p></li><li><p>微扰理论经常写算法题解，最近正在学习数学基础知识。</p></li></ol><p>我们可以对文档进行分词，并建立倒排索引。以“极客”、“理论”、“学习”这几个词所对应的倒排列表为例，得到类似于下图的索引结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>极客 -&gt; 1 2</span></span>
<span class="line"><span>理论 -&gt; 2 3 4</span></span>
<span class="line"><span>学习 -&gt; 2 4</span></span>
<span class="line"><span>数学 -&gt; 3 4</span></span></code></pre></div><p>直接检索某个关键字的结果当然是显而易见的，那如果我们需要对多个关键词进行与查询如何做呢？</p><p>其实就是对这些关键词的倒排索引取交集的过程，具体实现方式和数据库的 join 很像，我们既可以用 hash 表来实现，也可以用排序 + 归并的方式实现，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>极客 &amp; 理论 -&gt; 2</span></span>
<span class="line"><span>数学 &amp; 理论 -&gt; 3</span></span>
<span class="line"><span>理论 &amp; 学习 -&gt; 2 4</span></span></code></pre></div><p>从这个具体的例子里，相信你也能感受到，关键词匹配出来的文档应该是很多的，那如何排序呢？</p><p>因为倒排索引常用于信息检索，而信息检索质量的一个很重要的指标是文档和关键词的相关性，所以，有时候倒排索引还会在倒排列表中增加每个单词在特定文档中出现的次数，也就是词频信息。</p><p>在早年大数据、统计学习乃至深度学习没有得到广泛应用时，词频信息，是文档和关键词匹配度最重要的指标之一，记录了词频信息，就可以让我们在倒排索引中对检索结果进行简单的排序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>学完今天的内容，倒排索引的基本概念还是非常好理解的。虽然思想朴素，但是它的工业实现却非常复杂。</p><p>因为在倒排使用的场景中，所需存储查询的数据量通常很大，同时，对检索时延的要求又很高，无论是搜索引擎、推荐系统还是广告系统，每次检索的时间都要求在几十到几百毫秒以内，这就导致我们需要对倒排索引的实现持续做性能优化。</p><p>Lucene 就是一个非常值得学习的全文搜索引擎库，它在数据结构上做了非常多巧妙的优化，知名的搜索引擎 Elasticsearch 就是建立在 Lucene 的基础之上实现的。</p><p>不过限于篇幅，我们今天就不对倒排索引的工业实现做展开讲解了，因为内容真的非常非常多，希望你感兴趣的话可以结合着 lucene 的源码细细品味。</p><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>如果现在让你实现一个倒排索引的库，那你会如何设计倒排列表的存储方式呢？如果要让多关键词的与查询尽量快速，你会如何设计取交集的算法呢？</p><p>欢迎你在留言区分享你的思考，如果觉得这篇文章对你有帮助的话也欢迎你转发给你的朋友一起学习。</p>`,41)])])}const d=a(p,[["render",n]]);export{E as __pageData,d as default};
